INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('Выборы в Государственную Думу: выдвижение и агитация','Во время кампании партия призывает голосовать против определённого федерального списка. Является ли такое действие предвыборной агитацией?','["Да, закон прямо включает побуждение голосовать против списка","Нет, агитацией признаются только призывы голосовать за","Нет, поскольку речь идёт не о конкретном кандидате","Да, но только если список зарегистрирован муниципальной комиссией"]'::jsonb,0,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 9','https://www.consultant.ru/document/cons_doc_LAW_159349/f83d7472edead53d2aa27710c78fba4633858d4f/','Часть 2 статьи 9 охватывает агитацию за и против списков.',true),
('Выборы в Государственную Думу: выдвижение и агитация','Воскресенье назначенного голосования совпало с нерабочим праздничным днём. Как поступить согласно 20-ФЗ?','["Назначить выборы на следующее воскресенье","Перенести на предыдущую субботу","Отменить выборы до следующего года","Провести голосование только по партийным спискам"]'::jsonb,0,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 5','https://www.consultant.ru/document/cons_doc_LAW_159349/59e57ebdaabb89ca39f6ec710b5e37e2bc114686/','Часть 7 статьи 5 предусматривает перенос на следующее воскресенье.',true),
('Выборы в Государственную Думу: выдвижение и агитация','Гражданин не состоит ни в одной политической партии. Может ли партия выдвинуть его в составе своего федерального списка?','["Нет, партия может выдвигать только собственных членов","Да, но лишь при наличии трёхлетнего партийного стажа","Да, если он не является членом другой партии и соблюдены остальные требования","Нет, беспартийный гражданин вправе только самовыдвигаться по списку"]'::jsonb,2,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_159349/5425d22034446e636b479c110ebf823c74fcf3bc/','Часть 4 статьи 6 допускает беспартийных кандидатов.',true),
('Выборы в Государственную Думу: выдвижение и агитация','Гражданин обладает пассивным избирательным правом и хочет самостоятельно выдвинуться по одномандатному округу. Допускает ли закон этот способ?','["Да, непосредственное выдвижение включает самовыдвижение","Нет, все кандидаты обязаны входить в партийный список","Да, но только с утверждением кандидатуры Советом Федерации","Нет, самовыдвижение допускается лишь на выборах Президента РФ"]'::jsonb,0,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_159349/5425d22034446e636b479c110ebf823c74fcf3bc/','Часть 2 статьи 6 предусматривает самовыдвижение.',true),
('Выборы в Государственную Думу: выдвижение и агитация','Гражданин хочет самостоятельно выдвинуть федеральный список кандидатов, не создавая политической партии. Возможно ли это?','["Да, самовыдвижение допускается и для федеральных списков","Нет, федеральные списки выдвигаются политическими партиями","Да, если список поддержан половиной губернаторов","Да, после постановления Правительства РФ"]'::jsonb,1,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_159349/5425d22034446e636b479c110ebf823c74fcf3bc/','Часть 3 статьи 6 оставляет выдвижение федеральных списков политическим партиям.',true),
('Выборы в Государственную Думу: выдвижение и агитация','Избирательная комиссия утверждает, что граждане вправе агитировать только в форме публичного митинга. Что предусматривает закон?','["Агитация допускается только на телевидении","Агитация возможна исключительно через государственные СМИ","Допускаются различные законные формы и методы предвыборной агитации","Форму агитации для всех кампаний единолично определяет кандидат"]'::jsonb,2,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 9','https://www.consultant.ru/document/cons_doc_LAW_159349/f83d7472edead53d2aa27710c78fba4633858d4f/','Часть 1 статьи 9 допускает законные формы и методы агитации.',true),
('Выборы в Государственную Думу: выдвижение и агитация','Кандидат имеет право быть избранным, но не хочет вступать в партию. Какие варианты непосредственного выдвижения предусмотрены законом?','["Только выдвижение в федеральном списке без решения партии","Самовыдвижение или выдвижение политической партией, в которую он не обязан вступать","Только назначение кандидатом Президентом","Только выдвижение органом государственной власти субъекта РФ"]'::jsonb,1,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_159349/5425d22034446e636b479c110ebf823c74fcf3bc/','Статья 6 допускает самовыдвижение и выдвижение беспартийных партией.',true),
('Выборы в Государственную Думу: выдвижение и агитация','На выборах Государственной Думы гражданин одновременно просит партию выдвинуть его в федеральный список и по одномандатному округу; какие виды выдвижения рассматривает закон?','["Только выдвижение через орган местного самоуправления","Только внесение кандидатуры Президентом","Только самовыдвижение внутри пропорционального списка","Непосредственное по одномандатному округу и выдвижение в составе федерального списка"]'::jsonb,3,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_159349/5425d22034446e636b479c110ebf823c74fcf3bc/','Статья 6 различает непосредственное выдвижение и выдвижение по федеральным спискам.',true),
('Выборы в Государственную Думу: выдвижение и агитация','Партия зарегистрировала федеральный список и просит равного доступа к СМИ на условиях избирательной агитации. Каков предусмотренный законом принцип?','["Преимущественный доступ только для парламентских партий","Возможность отказа всем зарегистрированным кандидатам без оснований","Доступ определяется исключительно числом региональных отделений партии","Равные условия доступа к СМИ для зарегистрированных кандидатов и партий со списками"]'::jsonb,3,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 9','https://www.consultant.ru/document/cons_doc_LAW_159349/f83d7472edead53d2aa27710c78fba4633858d4f/','Часть 4 статьи 9 гарантирует равные условия доступа.',true),
('Выборы в Государственную Думу: выдвижение и агитация','Партия предложила включить в федеральный список кандидата, состоящего в другой политической партии. Какое ограничение действует?','["Выдвигать возможно после любого устного согласия кандидата","Запрет касается только одномандатных округов","Членство в другой партии не влияет на выдвижение ни в каких случаях","Выдвигать членов иных политических партий запрещено"]'::jsonb,3,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_159349/5425d22034446e636b479c110ebf823c74fcf3bc/','Часть 4 статьи 6 запрещает выдвижение членов иных партий.',true),
('Выборы в Государственную Думу: выдвижение и агитация','Партия хочет выдвинуть кандидата, являющегося её членом, по одномандатному округу. Допускает ли это федеральный закон?','["Нет, по округу могут участвовать только беспартийные кандидаты","Да, но только при переходе члена в другую партию","Да, партия вправе выдвигать собственных членов","Нет, партийные кандидаты вправе участвовать только в пропорциональном голосовании"]'::jsonb,2,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_159349/5425d22034446e636b479c110ebf823c74fcf3bc/','Часть 4 статьи 6 допускает выдвижение членов своей партии.',true),
('Выборы в Государственную Думу: выдвижение и агитация','После принятия Президентом решения о назначении выборов Госдумы пресс-служба планирует опубликовать его через десять дней. Какой срок установлен законом?','["Не позднее семи дней со дня принятия решения","Не позднее четырнадцати дней со дня принятия решения","Не позднее пяти дней со дня принятия решения","Публикация допустима лишь после формирования избирательных фондов"]'::jsonb,2,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 5','https://www.consultant.ru/document/cons_doc_LAW_159349/59e57ebdaabb89ca39f6ec710b5e37e2bc114686/','Часть 2 статьи 5 требует опубликования в пятидневный срок.',true),
('Выборы в Государственную Думу: выдвижение и агитация','Президент пропустил срок назначения очередных выборов; ЦИК назначила выборы. Когда ЦИК должна опубликовать своё решение по общему правилу?','["Не позднее пяти дней после начала голосования","Не позднее семи дней со дня истечения срока публикации президентского решения","Не позднее тридцати дней до истечения мандата парламента","В течение месяца после регистрации всех кандидатов"]'::jsonb,1,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 5','https://www.consultant.ru/document/cons_doc_LAW_159349/59e57ebdaabb89ca39f6ec710b5e37e2bc114686/','Часть 3 статьи 5 устанавливает специальный семидневный срок.',true),
('Выборы депутатов Государственной Думы','В день выборов Госдумы гражданину исполняется 21 год; он постоянно проживает в РФ. Выполняет ли он возрастное условие пассивного избирательного права?','["Нет, требуется 25 лет на день назначения выборов","Да, минимальный возраст кандидата составляет 21 год ко дню голосования","Нет, требуется 30 лет на момент регистрации","Да, но лишь при наличии пятилетнего стажа госслужбы"]'::jsonb,1,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_159349/890384a59ec5164c4aebe6dc266bbaedb14dfd9b/','Часть 4 статьи 4 ФЗ № 20-ФЗ закрепляет возраст 21 год.',true),
('Выборы депутатов Государственной Думы','Гражданин выдвинут в Госдуму, но у него сохраняется счёт в банке за пределами России. Когда необходимо его закрыть для соблюдения закона?','["В течение месяца после вступления в депутатские полномочия","К моменту представления документов, необходимых для регистрации кандидата или федерального списка","Только после избрания депутатом","К началу следующего финансового года"]'::jsonb,1,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_159349/890384a59ec5164c4aebe6dc266bbaedb14dfd9b/','Часть 13 статьи 4 устанавливает крайний срок закрытия иностранных счетов.',true),
('Выборы депутатов Государственной Думы','Гражданин достиг 18 лет ко дню голосования, постоянно проживает за границей и имеет российское гражданство. Каков статус его избирательного права?','["Он сохраняет равные избирательные права, а дипломатические учреждения содействуют реализации","Он лишён избирательного права из-за проживания за рубежом","Он вправе голосовать только по одномандатному округу в России","Он имеет право голосовать только после возвращения за три месяца до выборов"]'::jsonb,0,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_159349/890384a59ec5164c4aebe6dc266bbaedb14dfd9b/','Часть 5 статьи 4 защищает российских избирателей за границей.',true),
('Выборы депутатов Государственной Думы','Гражданин, осуждённый к лишению свободы за тяжкое преступление, получил погашение судимости восемь лет назад. Какой общий срок ограничения пассивного права предусмотрен законом?','["Пять лет после снятия или погашения судимости","Пятнадцать лет после снятия или погашения судимости","Ограничение прекращается немедленно после погашения","Десять лет после снятия или погашения судимости"]'::jsonb,3,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_159349/890384a59ec5164c4aebe6dc266bbaedb14dfd9b/','Пункт 2 части 8 статьи 4 предусматривает десятилетний срок.',true),
('Выборы депутатов Государственной Думы','Избиратель зарегистрирован в одномандатном округе по месту пребывания за четыре месяца до голосования, по месту жительства — в другом. Когда он сможет голосовать по округу пребывания?','["Автоматически по одному лишь временному проживанию без заявления","Только при регистрации по месту пребывания не менее года","Только после отдельного разрешения ЦИК для каждого избирателя","При подаче предусмотренного заявления о включении в список по месту нахождения в этом одномандатном округе"]'::jsonb,3,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_159349/890384a59ec5164c4aebe6dc266bbaedb14dfd9b/','Часть 2 статьи 4 предусматривает трёхмесячную регистрацию и соответствующее заявление.',true),
('Выборы депутатов Государственной Думы','Кандидат обладает статусом иностранного агента. Может ли он сохранить его к моменту подачи документов на регистрацию?','["Нет, статус необходимо прекратить до представления регистрационных документов","Да, достаточно упомянуть статус в агитационных материалах","Да, статус препятствует только получению государственных субсидий","Да, если выдвижение происходит в одномандатном округе"]'::jsonb,0,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_159349/890384a59ec5164c4aebe6dc266bbaedb14dfd9b/','Часть 13.1 статьи 4 регулирует прекращение такого статуса.',true),
('Выборы депутатов Государственной Думы','Президент назначает очередные выборы Госдумы за 120 дней до дня голосования. Какой временной интервал установлен законом?','["Решение принимается между 120 и 150 днями","Решение принимается не раньше 110 и не позже 90 дней до голосования","Решение принимается строго за 60 дней до голосования","Решение принимается не ранее 90 и не позднее 70 дней"]'::jsonb,1,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 5','https://www.consultant.ru/document/cons_doc_LAW_159349/59e57ebdaabb89ca39f6ec710b5e37e2bc114686/','Часть 2 статьи 5 устанавливает окно 110–90 дней.',true),
('Выборы депутатов Государственной Думы','Президент не назначил очередные выборы Госдумы в отведённый срок. Кто вправе назначить их вместо него в предусмотренном законом порядке?','["Центральная избирательная комиссия Российской Федерации","Совет Федерации как палата субъектов","Председатель Правительства РФ своим распоряжением","Конституционный Суд РФ"]'::jsonb,0,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 5','https://www.consultant.ru/document/cons_doc_LAW_159349/59e57ebdaabb89ca39f6ec710b5e37e2bc114686/','Часть 3 статьи 5 передаёт назначение ЦИК при пропуске срока Президентом.',true),
('Выборы депутатов Государственной Думы','Президент распустил Государственную Думу. Как должна определяться дата досрочных выборов по общему правилу?','["Третье воскресенье месяца по истечении пяти лет","Первое воскресенье после даты роспуска","Последнее воскресенье перед истечением шести месяцев со дня роспуска","Последнее воскресенье перед истечением трёх месяцев со дня роспуска"]'::jsonb,3,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 5','https://www.consultant.ru/document/cons_doc_LAW_159349/59e57ebdaabb89ca39f6ec710b5e37e2bc114686/','Часть 4 статьи 5 устанавливает специальную дату досрочных выборов.',true),
('Выборы депутатов Государственной Думы','При судимости за особо тяжкое преступление, которая снята 12 лет назад, какое правило ограничения пассивного избирательного права применяется?','["Ограничение сохраняется только десять лет","Ограничение прекращается сразу после отбытия наказания","Ограничение сохраняется до истечения пятнадцати лет после снятия или погашения судимости","Ограничение длится двадцать лет при любой категории преступления"]'::jsonb,2,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_159349/890384a59ec5164c4aebe6dc266bbaedb14dfd9b/','Пункт 3 части 8 статьи 4 содержит срок пятнадцать лет.',true),
('Выборы депутатов Государственной Думы','У кандидата в Госдуму имеется вид на жительство иностранного государства. Как действует ограничение пассивного избирательного права?','["Иностранный вид на жительство влияет лишь на возможность голосовать","Ограничение действует только для сенаторов РФ","Такой документ препятствует избранию депутатом Государственной Думы","Ограничение устраняется решением местной избирательной комиссии"]'::jsonb,2,'Федеральный закон от 22.02.2014 № 20-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_159349/890384a59ec5164c4aebe6dc266bbaedb14dfd9b/','Часть 7 статьи 4 запрещает избрание лиц с иностранным гражданством или документом постоянного проживания.',true),
('Конституционные гарантии и обязанности','В момент поступка уголовной или административной ответственности за него не существовало. Допустимо ли наказание по закону, принятому позднее?','["Да, если позднейший закон определил большой штраф","Да, если согласовано с прокуратурой субъекта","Да, если поступок получил общественное осуждение","Нет, никто не отвечает за деяние, не признававшееся правонарушением при совершении"]'::jsonb,3,'Конституция Российской Федерации','статья 54','https://minjust.gov.ru/ru/documents/8011/','Часть 2 статьи 54 запрещает ретроактивное установление ответственности.',true),
('Конституционные гарантии и обязанности','В указе о чрезвычайном положении не указаны пределы и срок временных ограничений прав. Какое конституционное требование необходимо выполнить?','["Достаточно перечислить ведомства, исполняющие указ","Срок ограничений всегда определяется после отмены режима","Ограничения прав при ЧП вообще не нуждаются в правовом основании","Указать пределы и срок ограничений в рамках ФКЗ о чрезвычайном положении"]'::jsonb,3,'Конституция Российской Федерации','статья 56','https://minjust.gov.ru/ru/documents/8011/','Статья 56 требует пределов и срока отдельных временных ограничений.',true),
('Конституционные гарантии и обязанности','Ведомство отказывается признавать право на альтернативную гражданскую службу по мотивам убеждений, не связанных с религией. Какое положение имеет значение?','["Право связано также с убеждениями гражданина, которым противоречит несение военной службы","Право предусмотрено только для священнослужителей","Право возникает только после установления инвалидности","Право предоставляется лишь после окончания военной службы"]'::jsonb,0,'Конституция Российской Федерации','статья 59','https://minjust.gov.ru/ru/documents/8011/','Статья 59 учитывает убеждения и вероисповедание.',true),
('Конституционные гарантии и обязанности','Гражданин полагает, что обязан уплачивать только налог, установленный его муниципальным собранием. Как сформулирована общая конституционная обязанность?','["Обязанность распространяется только на федеральные налоги","Обязанность касается исключительно налогов для должностных лиц","Обязательны лишь добровольно согласованные налоговые платежи","Каждый обязан платить законно установленные налоги и сборы независимо от уровня их законного установления"]'::jsonb,3,'Конституция Российской Федерации','статья 57','https://minjust.gov.ru/ru/documents/8011/','Статья 57 устанавливает всеобщую обязанность платить законно установленные налоги и сборы.',true),
('Конституционные гарантии и обязанности','Гражданин пострадал от злоупотребления властью. Следует ли из статьи 52, что охрана прав потерпевших относится только к преступлениям частных лиц?','["Нет, статья охватывает также злоупотребления властью","Да, злоупотребление властью не упомянуто","Да, если вред причинён органом местного самоуправления","Да, поскольку применяется только гражданское законодательство"]'::jsonb,0,'Конституция Российской Федерации','статья 52','https://minjust.gov.ru/ru/documents/8011/','Защита распространяется и на злоупотребления властью.',true),
('Конституционные гарантии и обязанности','Гражданин РФ приобрёл иностранное гражданство в порядке, допустимом российским правом. Теряет ли он автоматически конституционные обязанности России?','["Нет, наличие иностранного гражданства само по себе не освобождает от обязанностей РФ","Да, гражданские обязанности РФ полностью прекращаются","Да, достаточно уведомить региональную администрацию","Нет, но права автоматически сокращаются наполовину"]'::jsonb,0,'Конституция Российской Федерации','статья 62','https://minjust.gov.ru/ru/documents/8011/','Статья 62 предусматривает сохранение прав и обязанностей, кроме законных исключений.',true),
('Конституционные гарантии и обязанности','Гражданин РФ спрашивает, с какого возраста он может самостоятельно осуществлять свои права и обязанности в полном объёме по общему конституционному правилу. Каков возраст?','["Шестнадцать лет","Двадцать один год","Двадцать пять лет","Восемнадцать лет"]'::jsonb,3,'Конституция Российской Федерации','статья 60','https://minjust.gov.ru/ru/documents/8011/','Статья 60 устанавливает совершеннолетие как общее правило.',true),
('Конституционные гарантии и обязанности','Гражданин требует компенсации за незаконное решение должностного лица, но ему отвечают, что Конституция защищает лишь от активных действий. Что неверно в таком ответе?','["Статья 53 охватывает только умышленные преступления","Статья 53 распространяется только на коллективные обращения","Статья 53 прямо охватывает и незаконное бездействие","Статья 53 устанавливает компенсацию лишь при отсутствии решения суда"]'::jsonb,2,'Конституция Российской Федерации','статья 53','https://minjust.gov.ru/ru/documents/8011/','Формулировка статьи 53 включает действия и бездействие.',true),
('Конституционные гарантии и обязанности','Гражданин указывает, что его вероисповеданию противоречит несение военной службы. Какую конституционную возможность необходимо рассмотреть?','["Безусловное освобождение от всех публичных обязанностей без процедуры","Замену военной службы альтернативной гражданской службой при условиях закона","Обязательную замену военной службы депутатскими полномочиями","Замену военной службы исключительно работой в выборной комиссии"]'::jsonb,1,'Конституция Российской Федерации','статья 59','https://minjust.gov.ru/ru/documents/8011/','Часть 3 статьи 59 предусматривает альтернативную гражданскую службу.',true),
('Конституционные гарантии и обязанности','Деяние было правонарушением, но позднее новый закон полностью устранил ответственность за него. Какое правило следует из Конституции?','["Применяется новый закон, устраняющий ответственность","Применяется исключительно прежний закон, действовавший на момент деяния","Решение о применении нового закона принимает только региональный парламент","Устранение ответственности действует только после конституционного референдума"]'::jsonb,0,'Конституция Российской Федерации','статья 54','https://minjust.gov.ru/ru/documents/8011/','Статья 54 предусматривает применение более мягкого закона.',true),
('Конституционные гарантии и обязанности','Законодатель утверждает, что права, прямо не перечисленные в Конституции, автоматически отрицаются государством. Каково верное понимание?','["Конституция исключает существование всех не перечисленных прав","Перечисление конституционных прав не отрицает другие общепризнанные права и свободы","Иные права возникают только после личного разрешения Президента","Общепризнанные права могут действовать лишь в отдельных субъектах"]'::jsonb,1,'Конституция Российской Федерации','статья 55','https://minjust.gov.ru/ru/documents/8011/','Часть 1 статьи 55 предотвращает отрицание других общепризнанных прав.',true),
('Конституционные гарантии и обязанности','Иностранный гражданин законно находится в России и требует применения общего принципа равных прав и обязанностей. Какова формула Конституции?','["Иностранцы обладают только имущественными правами","Иностранцы пользуются правами, но не несут никаких обязанностей","Равные права могут быть установлены только муниципальным уставом","Иностранцы и лица без гражданства пользуются правами и несут обязанности наравне с гражданами, кроме установленных законом или договором случаев"]'::jsonb,3,'Конституция Российской Федерации','статья 62','https://minjust.gov.ru/ru/documents/8011/','Часть 3 статьи 62 содержит общее правило равенства с исключениями.',true),
('Конституционные гарантии и обязанности','Иностранный гражданин преследуется за политические убеждения и запрашивает убежище в РФ. Какой конституционный институт предусмотрен?','["Автоматическое приобретение гражданства РФ без процедуры","Выдача иностранному государству независимо от характера преследования","Предоставление политического убежища иностранцам и лицам без гражданства в соответствии с международно-правовыми нормами","Предоставление иммунитета сенатора Российской Федерации"]'::jsonb,2,'Конституция Российской Федерации','статья 63','https://minjust.gov.ru/ru/documents/8011/','Статья 63 посвящена политическому убежищу.',true),
('Конституционные гарантии и обязанности','Компания считает охрану природы исключительно обязанностью государства, не касающейся частных лиц. Какой принцип закреплён статьёй 58?','["Сохранение окружающей среды возлагается только на федеральных министров","Природные богатства защищаются исключительно на территориях заповедников","Каждый обязан сохранять природу и окружающую среду, бережно относиться к природным богатствам","Конституция запрещает экологические обязанности юридическим и физическим лицам"]'::jsonb,2,'Конституция Российской Федерации','статья 58','https://minjust.gov.ru/ru/documents/8011/','Статья 58 содержит всеобщую экологическую обязанность.',true),
('Конституционные гарантии и обязанности','Муниципалитет предлагает ограничить основное право только местным постановлением ради удобства администрации. Какой уровень правового акта предусмотрен статьёй 55?','["Любое постановление муниципалитета при обосновании удобством","Протокол комиссии по соблюдению муниципальной дисциплины","Федеральный закон при наличии необходимых конституционно допустимых целей и соразмерности","Распоряжение главы ведомства независимо от целей ограничения"]'::jsonb,2,'Конституция Российской Федерации','статья 55','https://minjust.gov.ru/ru/documents/8011/','Статья 55 допускает ограничения прав федеральным законом и только в необходимой мере.',true),
('Конституционные гарантии и обязанности','Новый федеральный закон усиливает ответственность за поступок, совершённый до его вступления в силу. Какой принцип применим?','["Любой закон об ответственности всегда применяется к прошлым действиям","Закон, устанавливающий или отягчающий ответственность, обратной силы не имеет","Новый закон применяется к прошлым деяниям по решению органа дознания","Конституция не регулирует действие норм об ответственности во времени"]'::jsonb,1,'Конституция Российской Федерации','статья 54','https://minjust.gov.ru/ru/documents/8011/','Статья 54 запрещает обратную силу более строгой ответственности.',true),
('Конституционные гарантии и обязанности','Орган власти предлагает выслать гражданина РФ за пределы страны в качестве административной меры. Какая гарантия этому препятствует?','["Высылка допускается приказом регионального органа","Высылка возможна в качестве альтернативы штрафу","Гражданин РФ не может быть выслан за её пределы или выдан другому государству","Высылка допускается при отсутствии постоянной регистрации"]'::jsonb,2,'Конституция Российской Федерации','статья 61','https://minjust.gov.ru/ru/documents/8011/','Часть 1 статьи 61 защищает граждан России от высылки и выдачи.',true),
('Конституционные гарантии и обязанности','Орган власти предполагает при чрезвычайном положении исключить любое судебное обжалование. Какое правило Конституции препятствует этому?','["При ЧП все права безусловно могут быть приостановлены","Судебная защита сохраняется только в столице государства","Право на судебную защиту по статье 46 входит в число не подлежащих ограничению","Обжалование допускается лишь после окончания действия ЧП"]'::jsonb,2,'Конституция Российской Федерации','статья 56','https://minjust.gov.ru/ru/documents/8011/','Часть 3 статьи 56 исключает ограничение гарантий статей 46–54.',true),
('Конституционные гарантии и обязанности','Орган исполнительной власти незаконным бездействием причинил гражданину вред. На чьё возмещение указывает статья 53 Конституции?','["На обязательное возмещение исключительно виновным служащим из личных средств","На возмещение только общественным объединением потерпевших","На возмещение исключительно через региональный избирательный фонд","На возмещение государством вреда от незаконных действий или бездействия органов власти"]'::jsonb,3,'Конституция Российской Федерации','статья 53','https://minjust.gov.ru/ru/documents/8011/','Статья 53 предусматривает право на возмещение вреда государством.',true),
('Конституционные гарантии и обязанности','Потерпевший от преступления просит обеспечить доступ к правосудию и компенсацию ущерба. Какую обязанность государства непосредственно закрепляет Конституция?','["Заменить судебное разбирательство исключительно ведомственной проверкой","Обеспечить потерпевшему доступ к правосудию и компенсацию причинённого ущерба","Предоставлять компенсацию только после обращения к парламенту","Переложить гарантию доступа к правосудию исключительно на частные организации"]'::jsonb,1,'Конституция Российской Федерации','статья 52','https://minjust.gov.ru/ru/documents/8011/','Статья 52 защищает права потерпевших от преступлений и злоупотреблений властью.',true),
('Конституционные гарантии и обязанности','Предлагается ограничить достоинство личности на период чрезвычайного положения. Какое положение Конституции применимо?','["Все личные права автоматически приостанавливаются","Статья 21 относится к правам, не подлежащим ограничению даже в условиях ЧП","Достоинство защищено только при отсутствии угрозы безопасности","Статья 21 допускает ограничение простым распоряжением губернатора"]'::jsonb,1,'Конституция Российской Федерации','статья 56','https://minjust.gov.ru/ru/documents/8011/','Статья 21 упомянута в перечне части 3 статьи 56.',true),
('Конституционные гарантии и обязанности','Региональный орган просит начислить новый налог на период до вступления в силу установившего его закона. Какое правило действует?','["Законы, устанавливающие новые налоги, обратной силы не имеют","Обратная сила любого налога допускается при дефиците бюджета","Любой региональный налог применяется с даты внесения законопроекта","Ретроактивность налога определяется исключительно налоговой инспекцией"]'::jsonb,0,'Конституция Российской Федерации','статья 57','https://minjust.gov.ru/ru/documents/8011/','Статья 57 запрещает обратную силу законов, вводящих новые налоги.',true),
('Конституционные гарантии и обязанности','Россиянин находится за рубежом и обращается за защитой. Какую обязанность государства закрепляет статья 61?','["Обеспечивать гражданину назначение в зарубежный парламент","Гарантировать гражданам защиту и покровительство за пределами РФ","Автоматически освобождать от законодательства страны пребывания","Предоставлять гражданину иммунитет иностранного дипломата"]'::jsonb,1,'Конституция Российской Федерации','статья 61','https://minjust.gov.ru/ru/documents/8011/','Статья 61 гарантирует защиту и покровительство граждан за рубежом.',true),
('Конституционные гарантии и обязанности','Федеральный закон ограничивает свободу без связи с защитой конституционного строя, здоровья, нравственности, прав других лиц, обороны или безопасности. Какое требование нарушено?','["Ограничение должно быть необходимым для целей, прямо названных частью 3 статьи 55","Ограничение достаточно назвать целесообразным для ведомства","Любое ограничение допустимо при принятии простым большинством","Ограничение прав должно обязательно вводиться региональным уставом"]'::jsonb,0,'Конституция Российской Федерации','статья 55','https://minjust.gov.ru/ru/documents/8011/','Статья 55 содержит исчерпывающее конституционное основание ограничения прав в необходимой мере.',true),
('Парламентский статус и служебные ограничения','Депутат Госдумы проводит приём избирателей в округе. Как это соотносится со статусом депутата?','["Работа с избирателями является самостоятельной формой деятельности депутата","Работа с избирателями допустима только во время предвыборной кампании","Работа с избирателями относится исключительно к муниципальным депутатам","Приём избирателей требует передачи мандата другому лицу"]'::jsonb,0,'Федеральный закон от 08.05.1994 № 3-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_3637/61e6d6926f71917c95459f53e1a6dbc9dfedcd74/','Часть 2 статьи 7 признаёт работу с избирателями формой деятельности депутата.',true),
('Парламентский статус и служебные ограничения','Депутат Госдумы участвует в работе согласительной комиссии двух палат. Как квалифицируется это действие?','["Несовместимая с депутатскими полномочиями деятельность","Одна из прямо названных форм парламентской деятельности","Исключительно работа регионального законодательного собрания","Право, возникающее только после сложения депутатского мандата"]'::jsonb,1,'Федеральный закон от 08.05.1994 № 3-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_3637/61e6d6926f71917c95459f53e1a6dbc9dfedcd74/','Пункт «б» части 1 статьи 7 относит такую работу к формам деятельности.',true),
('Парламентский статус и служебные ограничения','Депутат Государственной Думы намерен вести оплачиваемый курс лекций в российском университете. Какова общая правовая оценка?','["Преподавательская деятельность относится к исключениям из запрета иной оплачиваемой деятельности","Любая преподавательская деятельность депутата запрещена","Допустимо только участие в управлении коммерческим университетом","Допускается лишь преподавание на безвозмездной основе при отдельном федеральном законе"]'::jsonb,0,'Федеральный закон от 08.05.1994 № 3-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_3637/64de3808da4068276f30b82ae348e03a3df2958d/','Пункт «в» части 2 статьи 6 допускает преподавательскую деятельность.',true),
('Парламентский статус и служебные ограничения','Депутат Государственной Думы хочет выехать за границу с частной целью без согласования с палатой. Какое правило действует после поправок 2024 года?','["Никакие частные поездки депутатов не требуют согласования","Согласование необходимо исключительно с муниципалитетом","Выезд за пределы России, кроме служебных командировок, подлежит согласованию в порядке и сроки совета палаты","Выезд согласуется только с политической партией депутата"]'::jsonb,2,'Федеральный закон от 08.05.1994 № 3-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_3637/64de3808da4068276f30b82ae348e03a3df2958d/','Часть 2.2-1 статьи 6 устанавливает обязательное согласование.',true),
('Парламентский статус и служебные ограничения','Депутат предложил использовать служебную оргтехнику для управления собственным бизнесом. Какое правило нарушается?','["Запрещено использовать служебное обеспечение для целей, не связанных с полномочиями","Служебное имущество свободно предоставляется для предпринимательства","Запрет касается только телефонной связи","Нецелевое использование допустимо по любому партийном решению"]'::jsonb,0,'Федеральный закон от 08.05.1994 № 3-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_3637/64de3808da4068276f30b82ae348e03a3df2958d/','Пункт «з» части 2 статьи 6 запрещает нецелевое использование служебных средств.',true),
('Парламентский статус и служебные ограничения','Парламентарий получил дорогой подарок на официальном протокольном мероприятии. Каков общий предусмотренный законом режим?','["Подарок всегда остаётся личной собственностью без оформления","Подарок автоматически передаётся региональной избирательной комиссии","Подарок может быть передан любому родственнику без учёта его статуса","Подарок признаётся федеральной собственностью и передаётся по акту соответствующей палате с возможностью выкупа по правилам"]'::jsonb,3,'Федеральный закон от 08.05.1994 № 3-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_3637/64de3808da4068276f30b82ae348e03a3df2958d/','Пункт «е» части 2 статьи 6 регулирует протокольные подарки.',true),
('Парламентский статус и служебные ограничения','Сенатор выступает с вопросами членам Правительства на заседании своей палаты. Относится ли это к предусмотренным законом формам деятельности?','["Нет, сенатор вправе обращаться только с судебными исками","Нет, такие вопросы разрешены только депутатам региональных парламентов","Да, вопросы членам Правительства названы формой парламентской деятельности","Да, но только при наличии распоряжения Президента по каждому вопросу"]'::jsonb,2,'Федеральный закон от 08.05.1994 № 3-ФЗ','статья 7','https://www.consultant.ru/document/cons_doc_LAW_3637/61e6d6926f71917c95459f53e1a6dbc9dfedcd74/','Пункт «ж» части 1 статьи 7 предусматривает такие вопросы.',true),
('Парламентский статус и служебные ограничения','Сенатор планирует одновременно проходить муниципальную службу на оплачиваемой должности. Как действует правило несовместимости?','["Допускается при согласии председателя муниципалитета","Совмещение полномочий сенатора с муниципальной службой запрещено","Допускается при отсутствии денежных вознаграждений за заседания Совета Федерации","Допускается, если служба осуществляется в другом субъекте РФ"]'::jsonb,1,'Федеральный закон от 08.05.1994 № 3-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_3637/64de3808da4068276f30b82ae348e03a3df2958d/','Пункт «б» части 2 статьи 6 запрещает нахождение на муниципальной службе.',true),
('Парламентский статус и служебные ограничения','Сенатор хочет войти в коллегиальный орган управления коммерческой организации с оплатой участия. Каково общее ограничение?','["Допускается любое участие после уведомления своего комитета","Участие в управлении коммерческой организацией запрещено, кроме специально предусмотренного безвозмездного участия по акту Президента или Правительства","Допускается при получении не более половины обычного вознаграждения","Допускается автоматически при владении акциями организации"]'::jsonb,1,'Федеральный закон от 08.05.1994 № 3-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_3637/64de3808da4068276f30b82ae348e03a3df2958d/','Пункт «г» части 2 статьи 6 ограничивает участие в управлении компаниями.',true),
('Парламентский статус и служебные ограничения','Сенатор, совмещающий в предусмотренном законом случае полномочия с мандатом депутата законодательного органа субъекта РФ, должен отказаться от деятельности в Совете Федерации ради региональных заседаний. Каково правило 2026 года?','["Полномочия сенатора автоматически прекращаются при региональном голосовании","Совмещение во всех случаях запрещено без исключений","Полномочия регионального депутата обязательно исполняются вместо деятельности сенатора","Полномочия регионального депутата осуществляются без отрыва от основной деятельности в Совете Федерации"]'::jsonb,3,'Федеральный закон от 08.05.1994 № 3-ФЗ','статья 6','https://www.consultant.ru/document/cons_doc_LAW_3637/64de3808da4068276f30b82ae348e03a3df2958d/','Часть 1.1 статьи 6 в редакции 2026 года устанавливает специальное исключение.',true),
('Политические партии и государство','В уставе партии указано 520 членов, но отсутствуют утверждённые цели и задачи в программе. Что необходимо дополнить?','["Цели и задачи партии должны быть изложены в уставе и программе","Достаточно числа членов и протокола заседания","Цели и задачи определяются только федеральным министерством","Отсутствие программы устраняется письменным согласием региональных парламентов"]'::jsonb,0,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_32459/6503b753e1e72a738f4f2fc522dcfe3cf08e4a10/','Статья 3 требует закрепления целей в уставе и программе.',true),
('Политические партии и государство','Должностное лицо объясняет преимущество одной партии при предоставлении административных ресурсов личным непартийным статусом. Как оценивается поведение?','["Запрет применяется только к партиям, членом которых является чиновник","Беспартийный чиновник вправе помогать любой партии в служебное время","Запрет использования должностных преимуществ действует в интересах любой партии независимо от членства лица","Применимость запрета зависит исключительно от решения руководства партии"]'::jsonb,2,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 10','https://www.consultant.ru/document/cons_doc_LAW_32459/9eb92445c3af5badc1f6a9263cd47969ce6664b1/','Часть 3 статьи 10 охватывает любую политическую партию.',true),
('Политические партии и государство','Муниципальный орган рассматривает вопрос, прямо затрагивающий интересы зарегистрированной партии. Какой порядок предусматривает статья 10?','["Решать все подобные вопросы исключительно на закрытых заседаниях","Направлять любой вопрос только в Конституционный Суд","Решать вопрос с участием соответствующей партии либо по согласованию с ней","Не учитывать интересы партии ни при каких обстоятельствах"]'::jsonb,2,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 10','https://www.consultant.ru/document/cons_doc_LAW_32459/9eb92445c3af5badc1f6a9263cd47969ce6664b1/','Часть 2 статьи 10 устанавливает участие либо согласование.',true),
('Политические партии и государство','Муниципальный служащий использует служебный транспорт и помещение, чтобы предоставить преимущества своей партии. Какое ограничение нарушено?','["Запрет на членство муниципальных служащих в любой партии без исключений","Запрет использовать преимущества должностного положения в интересах любой партии","Обязанность работников муниципалитета поддерживать партию, победившую на выборах","Разрешение использовать служебные ресурсы при любой неформальной договорённости"]'::jsonb,1,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 10','https://www.consultant.ru/document/cons_doc_LAW_32459/9eb92445c3af5badc1f6a9263cd47969ce6664b1/','Часть 3 статьи 10 запрещает использование служебных преимуществ.',true),
('Политические партии и государство','Партия решила создать в одном субъекте два самостоятельных региональных отделения. Какой организационный принцип нарушается?','["Количество отделений всегда определяется числом муниципальных округов","Количество отделений устанавливает избирательная комиссия при каждом голосовании","В каждом субъекте может быть только одно региональное отделение партии","Допускается несколько отделений при разной численности участников"]'::jsonb,2,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_32459/6503b753e1e72a738f4f2fc522dcfe3cf08e4a10/','Статья 3 не допускает нескольких региональных отделений одной партии в субъекте.',true),
('Политические партии и государство','Партия создана для участия граждан в политической жизни, выборах и представительства их интересов. Как это квалифицируется по 95-ФЗ?','["Не соответствует, поскольку партия может заниматься только агитацией","Не соответствует, поскольку представительство интересов граждан запрещено","Соответствует только определению коммерческой корпорации","Соответствует законному определению политической партии как общественного объединения"]'::jsonb,3,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_32459/6503b753e1e72a738f4f2fc522dcfe3cf08e4a10/','Статья 3 определяет участие в выборах и представительство интересов как цели партии.',true),
('Политические партии и государство','Партия требует от государственного гражданского служащего выполнить политическое решение, противоречащее его должностным обязанностям. Какое правило применяется?','["Любое партийное решение выше должностного регламента служащего","Служащий связан партией даже при отсутствии членства","Решение партии может отменять применимый федеральный закон","Служащий не связан решениями партии при исполнении обязанностей с учётом законных исключений для избранных представителей"]'::jsonb,3,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 10','https://www.consultant.ru/document/cons_doc_LAW_32459/9eb92445c3af5badc1f6a9263cd47969ce6664b1/','Часть 3 статьи 10 исключает связанность партийными решениями для служащих.',true),
('Политические партии и государство','Президент РФ решил приостановить своё членство в партии на срок осуществления полномочий. Допускает ли это закон?','["Да, такое право прямо предусмотрено статьёй 10","Нет, приостановление членства запрещено","Да, но только по постановлению Государственной Думы","Нет, членство обязательно прекращается бессрочно"]'::jsonb,0,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 10','https://www.consultant.ru/document/cons_doc_LAW_32459/9eb92445c3af5badc1f6a9263cd47969ce6664b1/','Часть 4 статьи 10 допускает приостановление членства.',true),
('Политические партии и государство','Руководство партии пытается отдавать обязательные служебные распоряжения федеральному ведомству. Что предусматривает закон?','["Обязательное исполнение любого решения партийного съезда государственным органом","Право партий назначать руководителей федеральных министерств","Право партии приостанавливать действие федеральных законов","Невмешательство политических партий в деятельность государственных органов"]'::jsonb,3,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 10','https://www.consultant.ru/document/cons_doc_LAW_32459/9eb92445c3af5badc1f6a9263cd47969ce6664b1/','Часть 1 статьи 10 предусматривает взаимное невмешательство.',true),
('Политические партии и государство','Устав партии предусматривает создание первичных отделений. Откуда следует порядок их учреждения?','["Исключительно из индивидуального указа Президента РФ","Из устава партии в рамках действующего законодательства","Из регламента Совета Федерации независимо от устава","Из решения регионального правительства о структуре всех партий"]'::jsonb,1,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_32459/6503b753e1e72a738f4f2fc522dcfe3cf08e4a10/','Статья 3 допускает местные и первичные отделения в порядке устава.',true),
('Политические партии и государство','Учредители предлагают считать достаточным создание региональных отделений в 49 процентах субъектов РФ. Соответствует ли это закону?','["Да, закон устанавливает минимум в одну треть субъектов","Нет, требуется не менее половины субъектов РФ","Да, при наличии не менее ста членов в каждом отделении","Нет, необходимо обязательное присутствие во всех субъектах РФ"]'::jsonb,1,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_32459/6503b753e1e72a738f4f2fc522dcfe3cf08e4a10/','Статья 3 требует региональные отделения не менее чем в половине субъектов.',true),
('Политические партии и государство','Федеральное министерство хочет самостоятельно назначить руководство политической партии. Какой принцип законодательства нарушается?','["Невмешательство государственных органов в деятельность политических партий","Правило о недопустимости финансирования муниципалитетов","Принцип обязательной государственной собственности на партийное имущество","Право федерального органа утверждать партийный устав в любой редакции"]'::jsonb,0,'Федеральный закон от 11.07.2001 № 95-ФЗ','статья 10','https://www.consultant.ru/document/cons_doc_LAW_32459/9eb92445c3af5badc1f6a9263cd47969ce6664b1/','Часть 1 статьи 10 запрещает вмешательство органов власти в деятельность партий.',true)
